use vstd::prelude::*;

verus! {

/// Append two vectors of f32, preserving order.
/// 
/// Ensures:
///   - The length of the result is the sum of the lengths of the inputs.
///   - The first `arr.len()` elements of `result` match `arr`.
///   - The next `values.len()` elements of `result` match `values`.
fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> (result: Vec<f32>)
    ensures
        // length is the sum
        result.len() == arr.len() + values.len(),
        // prefix from arr
        forall |i: usize| i < arr.len() ==> result@ [i] == arr@ [i],
        // suffix from values
        forall |j: usize| j < values.len() ==> result@ [arr.len() + j] == values@ [j],
{
    // Pre-allocate capacity for efficiency
    let mut res: Vec<f32> = Vec::with_capacity(arr.len() + values.len());

    // First, copy all elements from `arr`
    let mut i: usize = 0;
    while i < arr.len()
        invariant
            i <= arr.len(),
            res.len() == i,
            // the first `i` elements of `res` match `arr`
            forall |k: usize| k < i ==> res@ [k] == arr@ [k],
        decreases arr.len() - i
    {
        // push the i-th element of arr
        res.push(arr[i]);
        i += 1;
    }

    // Next, copy all elements from `values`
    let mut j: usize = 0;
    while j < values.len()
        invariant
            j <= values.len(),
            // total length after copying `j` elements of `values`
            res.len() == arr.len() + j,
            // the prefix from `arr` is still correct
            forall |k: usize| k < arr.len() ==> res@ [k] == arr@ [k],
            // the next `j` elements match the first `j` of `values`
            forall |k: usize| k < j ==> res@ [arr.len() + k] == values@ [k],
        decreases values.len() - j
    {
        // push the j-th element of values
        res.push(values[j]);
        j += 1;
    }

    // At this point, res.len() == arr.len() + values.len()
    res
}

}

fn main() {
    // Example usage (not verified):
    let a = vec![1.0f32, 2.0, 3.0];
    let b = vec![-1.0f32, -2.0];
    let c = numpy_append(a.clone(), b.clone());
    assert!(c.len() == a.len() + b.len());
    for i in 0..a.len() {
        assert!(c[i] == a[i]);
    }
    for j in 0..b.len() {
        assert!(c[a.len() + j] == b[j]);
    }
}